async (page) => {
  return await page.evaluate(() => {
    const cards = [...document.querySelectorAll('section.fb-card')].filter(c => c.querySelector(':scope > img.fb-image'));
    const details = cards.map((c, i) => {
      const img = c.querySelector(':scope > img.fb-image');
      const title = c.querySelector(':scope > p[data-variant="title"]');
      const description = c.querySelector(':scope > p[data-variant="description"]');
      const rect = c.getBoundingClientRect();
      const cs = getComputedStyle(c);
      return {
        i,
        variant: c.dataset.variant,
        imgCount: c.querySelectorAll(':scope > img.fb-image').length,
        titleCount: c.querySelectorAll(':scope > p[data-variant="title"]').length,
        descriptionCount: c.querySelectorAll(':scope > p[data-variant="description"]').length,
        title: title?.textContent?.trim(),
        descriptionLength: description?.textContent?.trim().length || 0,
        imageSrc: img?.getAttribute('src'),
        imageComplete: !!img?.complete,
        naturalWidth: img?.naturalWidth || 0,
        naturalHeight: img?.naturalHeight || 0,
        left: rect.left,
        right: rect.right,
        width: rect.width,
        backgroundColor: cs.backgroundColor,
        color: cs.color
      };
    });
    const bad = details.filter(x => x.imgCount !== 1 || x.titleCount !== 1 || x.descriptionCount !== 1 || !x.title || !x.descriptionLength || !x.imageSrc || !x.imageComplete || x.naturalWidth === 0 || x.naturalHeight === 0);
    const variants = {};
    for (const x of details) variants[x.variant] = (variants[x.variant] || 0) + 1;
    return {
      viewport: { innerWidth, innerHeight, devicePixelRatio },
      document: { clientWidth: document.documentElement.clientWidth, scrollWidth: document.documentElement.scrollWidth, bodyScrollWidth: document.body.scrollWidth, horizontalOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth },
      cards: details.length,
      variants,
      alternates: details.every((x, i) => x.variant === (i % 2 === 0 ? 'sky' : 'dark')),
      backgrounds: [...new Set(details.map(x => x.variant + ':' + x.backgroundColor + ':' + x.color))],
      badCount: bad.length,
      bad: bad.slice(0, 5),
      first: details[0],
      last: details[details.length - 1],
      offViewportCount: details.filter(x => x.left < 0 || x.right > document.documentElement.clientWidth).length
    };
  });
}

