async (page) => {
  const responsePromise = page.waitForResponse(r => r.url().includes('/projects/sample_HelloWorldFlowRun10/.json') && r.request().method() === 'POST');
  await page.getByRole('button', { name: 'Load NASA News' }).click();
  const response = await responsePromise;
  const payload = await response.json();
  await page.waitForFunction(expected => document.querySelectorAll('section.fb-card > img.fb-image').length === expected, payload.count);
  return await page.evaluate(payload => {
    const cards = [...document.querySelectorAll('section.fb-card')].filter(c => c.querySelector(':scope > img.fb-image'));
    const mismatches = [];
    payload.news.forEach((item, i) => {
      const card = cards[i];
      const actual = {
        title: card?.querySelector(':scope > p[data-variant="title"]')?.textContent?.trim() || '',
        description: card?.querySelector(':scope > p[data-variant="description"]')?.textContent?.trim() || '',
        imageUrl: card?.querySelector(':scope > img.fb-image')?.getAttribute('src') || ''
      };
      if (actual.title !== item.title || actual.description !== item.description || actual.imageUrl !== item.imageUrl) mismatches.push({ i, expected: item, actual });
    });
    return { responseStatus: 200, backendCount: payload.count, backendArrayLength: payload.news.length, renderedCards: cards.length, exactTitleDescriptionImageMatches: payload.news.length - mismatches.length, mismatchCount: mismatches.length, mismatches: mismatches.slice(0, 3) };
  }, payload);
}

